local Blueprints=include("rhenium_contraption_blueprints/blueprints.lua");local Server={HookPrefix="RheniumContraptionBlueprints",TimerName="RheniumContraptionBlueprints.Save"};local core,installed=nil,false;local players,entities={},{}
local function validp(p)return IsValid(p)and p:IsPlayer()end;local function validid(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")end;local function validrev(v)return type(v)=="number"and v>=1 and v%1==0 and v<math.huge end;local function xyz(v)return{x=v.x or 0,y=v.y or 0,z=v.z or 0}end
local function endpoint(v)if IsValid and IsValid(v)and v.EntIndex then return v:EntIndex()end;if type(v)=="table"then return v.Index or v.Entity or v[1]end;return v end
local function constraint_signatures(rows)local out={};for _,c in pairs(rows or{})do local a,b=endpoint(c.Ent1),endpoint(c.Ent2);if a==nil or b==nil or type(c.Type)~="string"then return nil end;a,b=tostring(a),tostring(b);if b<a then a,b=b,a end;out[#out+1]=c.Type.."|"..a.."|"..b end;table.sort(out);return out end
local function graph_from_copy(copied,listed)
 local from_copy,from_table=constraint_signatures(copied.Constraints),constraint_signatures(listed);if not from_copy or not from_table or#from_copy~=#from_table then return nil end;for i=1,#from_copy do if from_copy[i]~=from_table[i]then return nil end end
 local graph={entities={},constraints={}};for k,e in pairs(copied.Entities or{})do graph.entities[#graph.entities+1]={source_id=tostring(k),class=e.Class or"prop_physics",model=e.Model,pos=xyz(e.Pos or Vector(0,0,0)),ang=xyz(e.Angle or Angle(0,0,0))}end
 for _,c in pairs(copied.Constraints or{})do graph.constraints[#graph.constraints+1]={type=c.Type,a=tostring(endpoint(c.Ent1)),b=tostring(endpoint(c.Ent2)),params={Bone1=c.Bone1 or 0,Bone2=c.Bone2 or 0,forcelimit=c.forcelimit or 0,nocollide=c.nocollide or false}}end;return graph
end
function Server.Install(o)if installed then return Server end;o=o or{};core=assert(Blueprints.new({state=o.state}));hook.Add("PlayerDisconnected",Server.HookPrefix..".Disconnect",function(p)players[p]=nil end);hook.Add("EntityRemoved",Server.HookPrefix..".Removed",function(e)entities[e]=nil end);timer.Create(Server.TimerName,5,0,function()if core then core:save()end end);installed=true;return Server end
function Server.BindPlayer(p,id)if not installed or not validp(p)or not validid(id)then return false end;players[p]=id;return true end;function Server.BindEntity(e,id,revision)if not installed or not IsValid(e)or not validid(id)or not validrev(revision)then return false end;entities[e]={id=id,revision=revision};return true end
function Server.Capture(p,root,name,rid,revision)if not players[p]or not entities[root]or not IsValid(root)then return false,"unbound",{}end;local trace={Entity=root};if hook.Run("CanTool",p,trace,"duplicator")==false then return false,"permission_denied",{}end;local public_constraints=constraint.GetTable(root);local copied=duplicator.Copy(root);if type(copied)~="table"or type(copied.Entities)~="table"or type(public_constraints)~="table"then return false,"capture_failed",{}end;local graph=graph_from_copy(copied,public_constraints);if not graph then return false,"capture_failed",{}end;return core:capture(rid,players[p],name,revision,graph)end
local function paste_tables(plan)local ents_data,map={},{};for i,e in ipairs(plan.entities)do map[e.id]=i;ents_data[i]={Class=e.class,Model=e.model,Pos=Vector(e.pos.x,e.pos.y,e.pos.z),Angle=Angle(e.ang.x,e.ang.y,e.ang.z),PhysicsObjects={[0]={Frozen=true}}}end;local cons={};for i,c in ipairs(plan.constraints)do local b1,b2=c.params.Bone1 or 0,c.params.Bone2 or 0;cons[i]={Type=c.type,Entity={{Index=map[c.a],Bone=b1},{Index=map[c.b],Bone=b2}},Bone1=b1,Bone2=b2,forcelimit=c.params.forcelimit or 0,nocollide=c.params.nocollide or false}end;return ents_data,cons end
function Server.Paste(p,name,target,rid,revision)if not players[p]or not validp(p)then return false,"unbound",{}end;if hook.Run("CanTool",p,{Entity=NULL},"duplicator")==false then return false,"permission_denied",{}end;local ok,code,plan=core:plan(rid,players[p],name,revision,xyz(target));if not ok then return ok,code,plan end;local data,cons=paste_tables(plan);local success,made,edges=pcall(duplicator.Paste,p,data,cons);made=made or{};edges=edges or{};local expected_e,expected_c=#plan.entities,#plan.constraints;local live_e,live_c=0,0;for _,e in pairs(made)do if IsValid(e)then live_e=live_e+1 end end;for _,e in pairs(edges)do if IsValid(e)then live_c=live_c+1 end end;if not success or live_e~=expected_e or live_c~=expected_c then for _,e in pairs(edges)do if IsValid(e)then e:Remove()end end;for _,e in pairs(made)do if IsValid(e)then e:Remove()end end;return false,"paste_failed",{entities=0,constraints=0}end;undo.Create("Rhenium Contraption Blueprint");for _,e in pairs(made)do undo.AddEntity(e);cleanup.Add(p,"props",e)end;for _,e in pairs(edges)do undo.AddEntity(e)end;undo.SetPlayer(p);if undo.Finish()~=true then for _,e in pairs(edges)do if IsValid(e)then e:Remove()end end;for _,e in pairs(made)do if IsValid(e)then e:Remove()end end;return false,"undo_failed",{entities=0,constraints=0}end;core:record_paste(rid,{entities=live_e,constraints=live_c});return true,"pasted",{entities=made,constraints=edges,hash=plan.hash}end
function Server.List(p)return players[p]and core:list(players[p])or{}end;function Server.Save()return core and core:save()end
function Server.Shutdown()if installed then hook.Remove("PlayerDisconnected",Server.HookPrefix..".Disconnect");hook.Remove("EntityRemoved",Server.HookPrefix..".Removed");timer.Remove(Server.TimerName);installed=false end;if core then core:shutdown()end;players={};entities={};return true,"shutdown"end;return Server
